    faq_a_bag_examples_list: "Yeni bir çanta, diğer her şey gibi değiştirilebilen ya da silinebilen örneklerle gelir: Ev (alışveriş, tarifler, haftanın yemekleri), Aile (küçük anlar, doğum günü partisi listesi, etkinlikler ve kurslar), Fikirler (hafta sonu fikirleri, kişiye ne kadar yakın olduğuna göre hediye fikirleri ve biriktirdiğin parayla ne yapacağın) ve Geziler (gitmek istediğin yerler, gezi için eşya listesi, otel için eşyalar ve yurt dışına uçuş listesi). Zaten var olan bir çanta en yenilerini bir kez, kendi ceplerine alır.",
