    faq_a_nm_me1_guide: "Sky – New Me'deki karakterin, ilk hâliyle (Sky 1). İlk seferde, katılır katılmaz etrafı ışıltılarla dolu bir ışık kapısı açılır ve Sky içinden uçarak çıkar, birkaç dokunuşta seni nelerin beklediğini anlatır, sonra her sorunun yanında kalır: öğünler seçilirken seninle birlikte kendi kitabına yazar, ipucuna dokununca bir başkası çıkar. Sonunda Sky seninle kutlama yapar ve seni kısa bir tura çıkarır – tur bitince de seninle küçük bir an daha paylaşır. Ortada – sorular ya da tur sırasında – çıkarsan, bir dahaki sefere Sky seni gördüğüne sevinir ve aynı yerden devam edip etmeyeceğini sorar.",
