    room_genie_again_no_msg: "O halde artık koyduğun hedeflere ulaşma zamanı. Bir sonrakine vardığında – orada seni bir şey bekliyor olacak ✨",
    room_genie_again_q: "Yine mi buradasın? ✨ Hayatında değiştirmek istediğin başka bir şey var mı?",
    room_genie_again_yes: "Evet",
    room_genie_bye: "Görüşürüz",
    room_genie_rest: "Orman ruhu şimdi dinleniyor – yarın tekrar gel ✨",
    faq_a_shop_holidays: "Alışveriş Listesi'nde hediyeye dokun: ülkenin (Ayarlar'da seçili olan) bayramları ve özel günleri sırayla, tarihleriyle birlikte görünür – tarihler her yıl kendiliğinden hesaplanır. Bir bayrama dokununca o gün için genelde alınanlardan oluşan hazır bir liste açılır; her şey seçilidir (listende zaten olanlar hariç), ihtiyacın olmayanların işaretini kaldır ve “Listeye ekle”ye dokun. Bir bayramdan iki hafta önce listenin en üstünde küçük bir kart çıkar; ✕ onu bir sonraki bayrama kadar gizler.",
    faq_q_shop_holidays: "“Bayram için ne alınır” nasıl çalışır?",
    shop_hol_add: "Listeye ekle ({n})",
    shop_hol_added: "Listeye eklendi: {n}",
    shop_hol_btn: "Bayram için ne alınır",
    shop_hol_items_title: "{holiday} – ne alınır?",
    shop_hol_not_now: "Şimdi değil",
    faq_a_shop_delivery: "Alışveriş Listesi'nde kamyona dokun: siparişte neler olduğunu (hepsi seçili gelir), ne zaman geleceğini – bugün, yarın ya da başka bir gün – ve hangi saatte geleceğini seç (sabah, öğlen, akşam ya da kendi saatlerin için “Diğer…”). Bu ürünler, günü ve saatleriyle birlikte listenin üstündeki “Yolda” kartına geçer. O gün geldiğinde Günüm'de “Sipariş geldi mi?” görünür (kartta da “Geldi mi?” vardır). Her şey geldiyse ürünler “Tekrar al” bölümüne geçer. Bir şey eksikse gelmeyene dokun, doğrudan listeye geri döner.",
    faq_a_shop_departments: "Liste kendini süpermarket reyonlarına göre sıralar – meyve ve sebze, ekmek, süt ürünleri ve yumurta, et ve balık, temel gıda, dondurulmuş, içecekler, atıştırmalık, temizlik, kişisel bakım, bebek ve evcil hayvan – böylece reyonları sırayla dolaşırsın. Reyon, ürünün adından anlaşılır. Bir ürün yanlış yere düştüyse ona dokun ve reyonunu seç ya da kendin yazmak için “Diğer…” seçeneğini seç.",
    faq_a_shop_share_qty: "Evet. Her ürünün yanında + bir tane ekler (×2, ×3…), − bir tane eksiltir. Alışveriş Listesi'nin üstündeki paylaş düğmesi, reyonlara göre düzgünce sıralanmış listenin tamamını WhatsApp, e-posta ya da kopya olarak gönderir.",
    faq_a_shop_two_buttons: "İkisi de “alındı” demek. ✕ bir kez aldığın şeyler için: ürün listeden çıkar (ve yanlışlık olursa diye 🗑️ arşivde bekler). ↺ tekrar tekrar aldığın şeyler için: ürün listeden çıkar ve “Tekrar al” bölümünde bekler; listenin en altında, çöp kutusunun yanındaki küçük ↺ düğmesi onu açar ve oraya bir dokunuş bir ürünü listeye geri koyar. İçindeki “Düzenle” ile bir ürünü oradan çıkarabilirsin. Ürün eklerken daha önce aldığın şeyler öneri olarak çıkar; ürün zaten listedeyse ikinci bir satır yerine sadece ×2 olur.",
    faq_q_shop_delivery: "“Teslimat siparişi verdim” nasıl çalışır?",
