    nm_demo_title: "Değişim nasıl yapılır",
    faq_a_new_me_challenge_journal: "Bir görev bittiğinde – büyük, mini ya da haftanın görevi – kutlamada bir 📝 Nasıl geçti? düğmesi olur. Bu düğme görev günlüğünde bir sayfa açar: nasıl hissettirdi (beş surat), ne yardımcı oldu, ne zordu ve yanımda ne götüreceğim – hiçbiri zorunlu değil, sonraya da kalabilir. Günlük, sihirli çantadaki bir elmastır: biten her görev tarihiyle ve yazılanlarla birlikte, en yenisi en üstte – okumak, düzenlemek ya da paylaşmak için birine dokun (yalnızca sayfadakiler paylaşılır). Biten görev ayrıca başarılarda, “Tamamladığım görevler” altında bir madalya kazanır. Görev günlüğü, normal günlükten ayrıdır.",
    faq_q_new_me_challenge_journal: "Görev günlüğü nedir?",
