    nm_chj_share_text: "New Me'de bir görevi tamamladım ✨",
    nm_chj_take: "Yanımda ne götüreceğim?",
    nm_chj_title: "Görev günlüğü",
    nm_chj_write: "Nasıl geçtiğini yaz",
    nm_swap_time: "Saat",
    faq_a_ai_reminder_in_text: "Evet – görevle birlikte yaz, örneğin “yarın 17:00'de paketi al, bir saat önce hatırlat”. Hatırlatıcı görevin kendisine kaydedilir: bir saat önce, yarım saat önce, bir gün önce vb.; saat belirtmeden yazılan “bana hatırlat” 10 dakika önce demektir. Metinde yazılan hatırlatıcı, aynı penceredeki hatırlatıcı alanına göre önceliklidir.",
    faq_q_ai_reminder_in_text: "Aynı istekte yapay zeka asistanından hatırlatıcı da isteyebilir miyim?",
    myday_meals_all_done: "Bugünün tüm öğünleri işaretlendi 🍽️",
    nm_tour_week_text: "Haftalık küçük bir görev. Her gün ✓ – sonunda bir anahtar.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "/ {total}",
    books_home_off_toast: "Kitap ana ekrandan kaldırıldı",
    books_home_on_toast: "Kitap ana ekranda 📖",
    books_home_pin: "Ana ekranda",
    books_home_q: "Kaçıncı sayfadayım?",
    books_home_save: "Kaydet",
    faq_a_books_home_chip: "Evet. Okuma Köşesi'nde, okuduğun bir kitabın kartında 📌 Ana ekranda öğesine dokun. Ana ekranda, karşılama mesajının altında kitabı ve sayfayı gösteren küçük bir düğme belirir – ona dokun, yeni sayfa numarasını yaz ve kaydet; ilerleme kaydedilir (Okuma Köşesi'nde de). 📌 öğesine tekrar dokunmak onu kaldırır. Birkaç kitap birlikte durabilir – her biri için bir düğme – ve her cihazda aynıdır.",
    faq_a_new_me_week_challenge: "Senin seçtiğin, bir haftalık küçük bir görev. Koridorda büyük bir kart var: “Bu hafta neyin üzerinde çalışmak istersin?” – dokun, bir alan seç (kendimle, başkalarıyla, öğren ve geliş, dinginlik, küçük cesur adımlar, ev ve rutin) ve bir görev seç, ardından ne zaman başlayacağını belirle. Aynı görevler Görevler ekranında da var, 🌱 Kişisel gelişim altında. Her gün karttaki ✓ simgesini işaretle (haftada bir gün serbest); biten her hafta gizli dünya için yeni bir anahtar getirir. “Günde 2 sayfa oku” görevi, Okuma Köşesi'ne kaydedilen sayfalardan kendiliğinden işaretlenir. Hafta bittiğinde 📌 Günlük görev olarak tut düğmesi onu seçtiğin saatte Rutinim'e ekler, her gün bir ✓ ile. Aynı anda yalnızca bir haftanın görevi sürer; büyük ve mini görevler onunla birlikte devam eder.",
    faq_a_room_genie: "Denize bakan verandada Alaaddin'in lambasına dokunmak orman ruhunu çıkarır – ve bir sohbet başlar: dileğin ne (hayatında neyi değiştirmek istersin), gerçekleşince nasıl hissettirecek, yolda ne zor ve şu anki durum nasıl iyiye çevrilebilir. Sonra yaklaşık ne kadar süreceği, küçük bir ilk adım ve iki adım daha, bir de zorlaştığı anlar için bir “eğer… o zaman…”. Sonunda dileğin tamamı adım adım görünür; Hedeflerim'de bir hedefe dönüştürülebilir (adımlar yoldaki duraklar olur, seçilen süreye göre tarihle; orada her şey değiştirilebilir) ya da günlüğe kaydedilebilir – ve ardından ruh vedalaşır. İkisinden biri seçilmezse hiçbir şey kaydedilmez. İkinci ziyaretten itibaren ruh önce hayatında değiştirmek istediğin başka bir şey olup olmadığını sorar: evet – aynı sohbet; şimdilik değil – önceden konan hedeflere ulaşmak için bir hatırlatma. Ruh günde bir kez çıkar: bir dilek kaydedildikten sonra (ya da “Şimdilik değil” seçildikten sonra) yarına kadar dinlenir. Sorular, bir dileği plana dönüştürmenin bilinen bir yolunu izler: dilek, sonuç, engel ve plan.",
    faq_q_books_home_chip: "Kitabımı ve sayfamı ana ekranda görebilir miyim?",
    faq_q_new_me_week_challenge: "Haftanın görevi nedir?",
