    nm_me_choose: "Seç",
    nm_me_on_screen: "Ekranda",
    faq_a_new_me_game: "New Me'de oyun düğmeleri hep aynı yerde kalır – koridorda, gizli odada ve ormanın her yerinde; yalnızca ortadaki resim değişir. Üstte: yolculuğun kaçıncı günü, anahtarlar, seri ve bugünün enerjisi (plandan ne kadarının yendiği), altında da sıradaki görev – kendi saatinde sıradaki öğün (dokununca açılır, ✓ Yedim ile birlikte). Yanda: bütün gün, görevler ve yolculuğum, onların yanında da haftanın görevi – 7 günü ve bugün için bir ✓. Altta: sihirli çanta (New Me'nin tamamı – dünya haritası, yolculuğum, alışveriş listesi, başarılar, görev günlüğü, vücut ölçüleri, ilerleme fotoları, aylık takvim, günlük tablo, hatırlatmalar, menü PDF'i ve ayarlar; ayrı bir ekran olarak açılır). Çantadaki ilk şey olan dünya haritası ormandaki her yeri gösterir – bir yere dokun, oraya git; kilitli bir yerde kaç anahtar gerektiği görünür. Sky, ormandaki patikada duran karakterin: Sky 1 olarak başlar, birkaç görevden sonra (4 anahtar) Sky 2'ye, sona doğru (9 anahtar) Sky 3'e dönüşür – izlenebilen bir değişimle. Tüm aşamaları görmek için Sky'a dokun – ulaşılmış her aşama yeniden seçilebilir, yani önceki aşama geri gelebilir. Sky süzülür; parmakla ya da fareyle sürüklenir ve dokunduğu giriş açılır (kilitli girişte kaç anahtarın eksik olduğu yazar). Sky her odaya ve her yere de seninle gelir ve onu nerede bırakırsan orada süzülür: onu istediğin yere sürükle, altındaki parlayan halkayı sürükleyerek de tamamen kendi etrafında döndür; hareket ettiği yöne bakar (bilgisayarda: oklar onu hareket ettirir, Q ve E döndürür). Koridorda, üst çubuğun altındaki küçük 🏠 ana ekrana geri döner; her odada ve her yerde, aynı köşedeki düğme koridora geri döner.",
    faq_q_new_me_game: "Oyun düğmeleri, dünya haritası ve Sky nasıl çalışır?",
