    faq_a_new_me_menu_build: "Önce anket hangi öğünleri ne zaman yediğini (2 öğün + bir ara öğün, 2 öğün + hafif bir akşam yemeği ya da ikisi de) ve akşam bir şey olup olmadığını sorar – yemek mi içmek mi, ne ve saat kaçta. “2 öğün + bir ara öğün” ile öğünler öğle yemeği (11:30) ve akşam yemeğidir (19:00), ara öğün de 16:00'da. Sonra bu öğünlerin tüm seçenekleri görünür. Her öğün için en fazla 2 favori seç – menüde “bu ya da şu” yazar. Bazı seçeneklerde (pita ve ezme, mısır gevreği ve süt, hafif bir şey) sevdiğin en fazla 3 şeyi seçersin, her biri kendi porsiyonuyla, ve menüde “bu ya da şu ya da şu” yazar; kaloriler seçtiklerine göre hesaplanır. Kahve ve içecekler de aynı şekilde çalışır. Her seçim dengelenir, böylece gün tam 1.300 ya da 1.500 eder. İstediğin zaman değiştirmek için: ⚙️ Ayarlar → 🍽️ Menünü oluştur ya da öğün kartındaki “Sevdiklerinden en fazla 3 tane seç”.",
