    faq_a_myday_water_toggle: "Evet. 'Günüm' içindeki su bardağı (bir bardak daha için + ile) varsayılan olarak görünür. Gizlemek için Ayarlar > Kişiselleştirme ve Takvim'de \"'Günüm' içinde suyu göster\" seçeneğini kapatın. Hiçbir şey silinmez – Su Takibi çalışmaya devam eder, tekrar açınca bardak geri gelir.",
    faq_q_myday_water_toggle: "'Günüm' içindeki suyu gizleyebilir miyim?",
    myday_water_toggle_label: "'Günüm' içinde suyu göster",
    faq_a_routine_newme_sync: "New Me varsa Rutinim'in ⚙️ menüsünde 'New Me ile senkronize et' anahtarı bulunur. Açıkken (varsayılan) bugünün New Me öğünleri Günüm'de ve Rutinim'de görünür – gizlenen rutin öğünlerinin yerinde. Kapalıyken New Me öğünleri ikisinden de çıkar ve rutin tam olarak eski haline döner. Hiçbir şey silinmez – yeniden açmak her şeyi geri getirir ve rutindeki hangi öğünlerin gizleneceğini sorar.",
