    theme_name_watercolor_wash: "Suluboya",
    faq_a_food_list_languages: "Yerleşik yiyecek listesi İsrail yemekleri ve İbranice adlarıyla başladı. Diğer tüm dillerde her yiyecek İngilizce adıyla görünür ve arama bildiği her İngilizce adı bulur (örneğin 'broth' Clear soup'u bulur); yalnızca İbranice adı olan yiyecekler listelenmez. Listede olmayan her şeyi kendi kelimelerinle yazabilirsin – AI tahmini her dilde çalışır.",
    faq_q_food_list_languages: "Yiyecek listesi benim dilimde neden İngilizce adlar ve daha az yiyecek gösteriyor?",
    settings_copyright_line: "© 2026 tüm hakları saklıdır. uygulamayı geliştiren: eden zabari.",
    workout_ready_replace_btn: "Değiştir",
    faq_a_sport_workout_ai: "\"Antrenmanlarım\" → ⋯ → \"AI ile plan\" (tablo boşken hazır planların yanındaki kutucuktan da). Birkaç dokunuşla cevapla – haftada kaç kez, ne zaman, yer, seviye ve hedef; çoğunda \"Diğer\" de var – istersen hassas bir diz ya da yaza kadar 5 km koşmak gibi serbest bir satır ekle. AI bütün bir hafta kurar: antrenman türleri, günler, saatler, süre, yoğunluk, egzersizler ve dinlenme günleri. Kaydetmeden önce bir önizleme gelir: \"Tabloma koy\" (tablonun yerine ya da ona ek olarak), \"Başka bir öneri\" (en fazla 3 kez) veya \"Cevapları değiştir\". Plan bilerek ılımlıdır; ağrı ya da sakatlıktan bahsedersen nazik seçenekler ve bir uzmana danışma önerisi gelir. Program ve rutin AI'ıyla aynı kotayı kullanır: 5 kez ücretsiz, Premium ile ayda 60 kez.",
    faq_q_sport_workout_ai: "AI ile antrenman planını nasıl oluştururum?",
