    workout_ai_working: "Plan hazırlanıyor…",
    faq_a_sport_workout_jar: "Her antrenman türünün kendi renkli yıldızı var – koşu pembe, yürüyüş yeşil, yüzme mavi ve böyle devam. Bu hafta kaydedilen her antrenman, tablodan ya da ayrıca, yıldızını \"Antrenmanlarım\"ın üstündeki kavanoza bırakır ve kavanoz haftalık hedefe doğru dolar (hedefi değiştirmek için ona dokun). Hedefe ulaşınca kavanoz parlar. Yanındaki küçük kavanoz, kaç hafta üst üste dolduğunu sayar.",
    faq_q_sport_workout_jar: "\"Antrenmanlarım\"daki renkli yıldızlar ve kavanoz nedir?",
    faq_a_sport_workout_gcal: "Evet – ⋯ → Google Takvim'den (Ayarlar'da Google Takvim bağlandıktan sonra). Saati olan her antrenman, kendi günlerinde her hafta tekrarlanan bir etkinliğe dönüşür ve uygulamadaki değişiklikler onu günceller. Hatırlatıcılar yalnızca uygulamadan gelir, bu yüzden Google kendi hatırlatıcısını eklemez ve antrenmanlar uygulamada asla iki kez görünmez. Tekrar dokunmak Google Takvim'den yalnızca antrenmanları kaldırır.",
    faq_q_sport_workout_gcal: "Antrenmanlarım Google Takvim'de görünebilir mi?",
    workout_gcal_btn: "Google Takvim",
    workout_gcal_error: "Google Takvim güncellenemedi – bir sonraki değişiklikte yeniden denenecek",
    workout_gcal_not_connected: "Önce Ayarlar'dan Google Takvim'i bağla",
    workout_gcal_off_toast: "Antrenmanlar Google Takvim'den kaldırıldı",
    workout_gcal_on_toast: "Antrenmanların Google Takvim'de",
    faq_a_sport_workout_reminder: "Evet – antrenmanda Hatırlatıcı: 10 dakika, 30 dakika ya da bir saat önce veya özel bir süre (antrenmanın bir saati olmalı). Diğer hatırlatıcıların sesiyle, bir kez ve tek bir yerde çalar: uygulama açıksa uygulamada, değilse telefonda. \"Bitti\" antrenmanı geçmişe kaydeder, \"Henüz değil\" 5 dakika sonra yeniden hatırlatır.",
    faq_q_sport_workout_reminder: "Antrenmandan önce hatırlatıcı alabilir miyim?",
    workout_reminder_30min: "30 dakika önce",
    workout_reminder_label: "Hatırlatıcı",
    workout_reminder_need_time: "Hatırlatıcı almak için bir saat ekle",
    faq_a_sport_workout_share: "⋯ → Paylaş'ta hafta, temanın renklerinde cam görünümlü bir görsele dönüşür ve uygulamaya hafif bir bağlantı eklenir (telefonda doğrudan paylaşım menüsüne gider, bilgisayarda görsel kaydedilir). ⋯ → Yazdırmak için PDF tüm haftanın sade bir sayfasını açar; her antrenmanın ve egzersizin yanında işaretlemek için bir kutu vardır – \"PDF olarak kaydet\"i seç ya da yazdır. Plan, Ayarlar'daki veri raporunun Spor bölümünde de yer alır.",
    faq_q_sport_workout_share: "Antrenman haftamı nasıl paylaşır ya da yazdırırım?",
    share_image_saved: "Görsel kaydedildi – ekleyebilirsin",
    share_save_image: "Görseli kaydet",
    workout_pdf_btn: "Yazdırmak için PDF",
    workout_share_btn: "Paylaş",
    faq_a_sport_workout_board: "⋯ → Haftalık pano'da her gün bir sütundur: antrenmanı başka bir güne sürükle (telefonda önce basılı tut). Bir antrenmanda \"Rutinim'de de\" onu kendi saatinde ve günlerinde rutinine koyar, değişiklikler iki yönde de eşitlenir; Rutinim'deki bir öğeden \"Antrenmanlarıma ekle\" bunun tersini yapar. Herhangi birindeki ✓ ikisinde de sayılır ve Günüm'de tek bir kez görünür – suyun yanındaki çipte.",
    faq_q_sport_workout_board: "Bir antrenmanı başka güne nasıl taşırım ve Rutinim'e nasıl bağlarım?",
    routine_in_workouts_btn: "Antrenmanlarımda aç",
    routine_to_workout_btn: "Antrenmanlarıma ekle",
    routine_to_workout_done: "Antrenmanlarıma eklendi 💪",
    workout_delete_confirm_routine: "Plandan ve Rutinim'den kaldırılacak. Geçmişe kaydedilmiş antrenmanlar kalır.",
    workout_moved: "{day} gününe taşındı",
    workout_routine_need_time: "Rutinim'e eklemek için bir saat ekle",
    workout_routine_toggle: "Rutinim'de de",
    workout_view_board: "Haftalık pano",
    workout_view_timeline: "Zaman çizelgesi",
    faq_a_sport_workout_plan: "Antrenman Takibi'nde, \"Antrenmanlarım\" altında: + Antrenman – tür, günler, saat, süre, yoğunluk ve yer (\"Diğer\" de var). Kuvvet, fonksiyonel ve yüzme antrenmanlarına egzersiz listesi eklenebilir; \"Dinlenme\" bir dinlenme gününü işaretler. Hazır bir planla da başlayabilirsin. Bugünün antrenmanı büyük görünür, altında tüm hafta; ✓ onu yoğunluğuyla birlikte antrenman geçmişine kaydeder. ⋯ içinde haftalık hedef belirlenir (antrenman ya da dakika); yapılan her antrenman kendi yıldızını kavanoza bırakır.",
    faq_a_sport_workout_today: "Günüm'de, suyun yanında küçük bir çip bugünün antrenmanını gösterir – dokununca ayrıntılar, ✓ ve ▶ açılır. ▶ bir zamanlayıcı başlatır, zamanlayıcı ana ekrandaki çipte de çalışmaya devam eder; \"Bitir\" antrenmanı gerçek süresiyle kaydeder. New Me'de \"Hareketli iki hafta\" meydan okuması sürüyorsa, kaydedilen antrenman orada kendiliğinden sayılır.",
