    faq_a_new_me_magic_themes: "New Me ile gelen beş ışıltılı tema: Büyülü Orman, Yıldız Tozu, Gül Perisi, Büyülü Kutup Işığı ve Altın Alacakaranlık. New Me içinde (⚙️ Ayarlar > Renkler) ya da Ayarlar > Görünüm ve Ekran'dan birini seç; ışıltılı bir fırça ekranı o temayla boyar. Büyülü tema tüm uygulamaya ve her dokunuşa ışıltı katar. İstediğin zaman başka bir temaya dönebilirsin.",
