    theme_magic_section_label: "New Me büyülü temaları",
    apptour_focus_text: "Şu anki tek iş dışında her şey kenara çekilir – kocaman bir ✓ ile. Sonra sıradaki görünür.",
    apptour_m_presets_text: "Kayıtlı öğünlerin tek yerde: arama, son kullanılanlar, günün saatine göre – ve ＋ birini bugüne ekler.",
    apptour_night_text: "🌙 tüm uygulamayı karartır, ☀️ günü geri getirir.",
    apptour_noteline_text: "Yaz ve ➤'ya dokun – notlarına kaydedilir. Baştaki 📝, 🛒 alışverişe ya da 🍎 kayıtlı bir öğüne geçer.",
    apptour_search_text: "Notlar, alışveriş, takvim, tarifler, defterler, hedefler, tablolar ve kitaplar – tek arama hepsini bulur.",
    faq_a_new_me_ai_menu: "Menüden önce anket hangi öğünleri ne zaman yediğini (2 öğün + bir ara öğün, 2 öğün + hafif bir akşam yemeği ya da ikisi), akşam küçük bir şey yiyip yemediğini ve saatini, neleri yemediğini ve kahve ya da çayı nasıl içtiğini sorar. Sonra yapay zekâ her öğün için 3 seçenek hazırlar – her biri o öğünün gündeki payı kadardır, böylece gün yine tam 1.300 ya da 1.500 eder – ve sabit içeceklerin olarak kaydedilen içecek fikirleri de verir. Her öğün için en fazla 2 favori seç; orijinal menünün seçenekleri hemen altındadır ve 🔄 Değiştir'de kişisel menünden sonra gelir. 🔄 Başka seçenekler yeni bir set hazırlar (her ankette 3 kez). Yanıtları değiştirmek ya da istediğin zaman yeni bir menü hazırlamak için: ⚙️ Ayarlar → ✨ Kişisel menü (YZ).",
    faq_q_new_me_ai_menu: "New Me'deki kişisel menü nasıl çalışır?",
