    nm_unlock_premium: "Premium'un tamamı da açıldı.",
    settings_sub_status_newme: "Premium, New Me'ne dahil.",
    room_back_to_shelf: "Rafa",
    faq_a_new_me_day_total: "Her gün tam olarak plana denk gelir: öğünler, gün içinde kahve ve içecekler için yaklaşık 150 kalori ve akşam için seçilen şey – yenecek küçük bir şey ya da bir içecek. Akşam için sevdiğin en fazla 3 şeyi seç (örneğin bir muz, bir yoğurt ya da 2 kare bitter çikolata; veya bitki çayı, az sütlü çay ya da ılık süt); kalorileri öğünlerden düşülür. Her seçim kendiliğinden dengelenir: daha küçük ya da büyük bir seçenek, çıkarılan bir öğün, küçük kahvaltı ve onunla gelen küçük öğün ya da akşam – fark öğünlere eklenir ya da onlardan düşülür, her birine boyutuna göre, ve her öğünün altında ne kadar (+ ya da −) ve neyin eklenip çıkarılabileceği yazar. Zaten işaretlenmiş bir öğün kaydedildiği gibi kalır. Ankette her öğünün yanında düzeltmesi görünür, küçük bir kutu da öğünleri, içecekleri, akşamı ve toplamı gösterir. O gün canın başka bir şey mi çekiyor? Toplamı aynı kaloride ya da daha az tut.",
    faq_q_new_me_day_total: "Bir New Me günü nasıl tam 1.300 / 1.500 ediyor, içecekler nerede sayılıyor?",
