    books_quotes_chip: "Alıntılar",
    faq_a_book_quotes: "Gizli odadaki rafta (Alıntılar) ya da Okuma Köşesi'ndeki küçük 💬 Alıntılar etiketinde – ikisi de aynı liste. \"+ Alıntı\"ya dokun, cümleyi yaz ve kitabı Okuma Köşesi'nden seç ya da \"✏️ Diğer\" ile başka bir ad yaz; yazar isteğe bağlı. ✏️ alıntıyı düzenler, 🗑️ siler. Alıntılar kaydırarak gezdiğin kitap ayraçlarıdır – üstteki 🎨 fotoğraflara ya da kartlardan bir duvara geçirir.",
    faq_a_room_wish_jar: "Gizli odadaki rafta hayaller için bir cam kavanoz var. En üst raftaki küçük kavanoza dokun (ya da Raf > Dilek kavanozu) ve hayatının nasıl olmasını istediğini yaz – istediğin kadar uçuk, doğrusu yanlışı yok. Her dilek bir nota katlanıp kavanoza düşer. \"Bir not çek\" rastgele birini açar; her not tek tek de açılabilir. Aynı dileği ikinci kez açtığında onu hedefe dönüştürüp küçük adımlara bölebilirsin. Haftada bir, dileklerinden birinin yazılı olduğu bir not yavaşça belirir – baskı yok, sadece nereye gittiğini hatırlatır.",
