    faq_a_notes_sticky_look: "Notlar, cam kartlardan oluşan kısa bir listedir – Notlar'ın üstündeki 🎨 tüm Notlar'ın görünümünü değiştirir: listeyi, üstteki gün düğmelerini ve notun yazıldığı pencereyi – cam, sade liste, fiş kartları veya washi bant. Sürüklenen not tam olarak kendi görünümünü ve rengini korur. Açmak için bir notun metnine dokun – orada düzenleyebilir, renklerini değiştirebilir ve en son ne zaman yazıldığını görebilirsin. İş bitince ○ işaretine dokun; × notu arşive taşır (listenin altındaki 🗑️ geri getirir). Sırayı değiştirmek, “Sonra” bölümünün altına almak ya da yukarıdaki bir güne bırakmak için ⠿ ile sürükle. ! bir notu acil olarak işaretler – not, küçük bir “Acil” etiketiyle yavaşça ilk sıralara kayar; bir dokunuş daha işareti kaldırır.",
    faq_q_notes_sticky_look: "Bir notu nasıl açar, düzenler veya kaldırırım?",
    note_to_archive_btn: "Arşive taşı",
    faq_a_routine_clash: "O saatte aynı günlerde zaten bir şey varsa iki seçenek çıkar: \"Değiştir\" – yeni öğe o saati alır ve öncekinin taşınacağı saati seçersiniz (var olan bir öğeyi düzenlerken onun eski saati önerilir, böylece ikisi kolayca yer değiştirir) ya da \"İkisi de\" – ikisi aynı saatte, alt alta kalır. Günler farklıysa (örneğin biri Paz–Per, diğeri cuma) hiçbir şey sorulmaz.",
