    faq_a_new_me_coffee: "Bugünün menüsünün altında kısa bir özet var: günün tüm öğünleri toplam kaç kalori, kahve ve içecekler için ne kadar kaldı ve seçilen kahve ve içeceklerin düğmeleri – tek dokunuşla İçecekler'e eklenir. Düğmelerin altındaki \"Sevdiklerinden en fazla 3 tane seç\" bölümünde (ve ankette) neyin görüneceğini seçersin: su / soda, bitki çayı, diyet içecek, sade / americano (~5), az sütlü çay (~25), en fazla 100 ml süt ya da bitkisel sütlü su bazlı kahve (~50), hafif sıcak çikolata, ılık süt ya da normal kahve / latte (~120).",
