    faq_a_recipe_examples: "Kendi tariflerinizin altında örnek tarifler var: kahvaltılar, salatalar, çorbalar, ana yemekler, garnitürler, atıştırmalıklar, tatlılar ve vegan yemekler. Her birinde hazırlama süresi, porsiyon başına kalori ve bir porsiyonun kaç gram olduğu yazar. Açmak için bir tarife dokunun; \"Tariflerime kaydet\" düzenleyebileceğiniz kendi kopyanızı oluşturur. Kategori etiketleri filtreler, aynı etikete tekrar dokunmak hepsini gösterir.",
    faq_a_recipe_grams: "Tarifin içinde, kalorinin yanında \"1 porsiyon ≈ X g\" yazar. Kendi tariflerinizde tarif formunda \"Porsiyon başına gram\"ı (isterseniz hazırlama süresini de) doldurun: ikisi de isteğe bağlıdır ve süre tarifin renkli şeridinde görünür.",
