    faq_a_recipe_scan_multi: "Evet. \"Tarif Ekle\"de 📷'a dokunun ve bir ya da birkaç fotoğraf seçin (en fazla 6; PDF de olur). Her biri kısa bir listede görünür ve içinde ne olduğunu seçersiniz: Hepsi, Malzemeler ya da Yapılışı; \"➕ Bir fotoğraf daha\" yenisini ekler. Sonra \"✨ Tarifi tara\"ya dokunun: yapay zekâ hepsini sırayla ve satırları tekrarlamadan tek bir tarifte birleştirir, bu da tek tarama sayılır. Yapay zekâ asistanındaki 📷 Fotoğraf'tan seçilen birkaç fotoğraf da burada açılır.",
