    faq_a_new_me_month: "Sihirli çantada → Aylık takvim: her gün kaç öğün işaretlendiğine göre renklenir, ‹ › okları aylar arasında geçiş yapar ve takvimin altında ayın günlük ortalama kalorisi yazar. Bir güne dokunmak o gün kaç öğün işaretlendiğini ve kaç kalori yendiğini gösterir.",
