    nm_extra_line_small: "Bu öğüne küçük kahvaltıdan {n} kalori – örneğin {ideas}",
    faq_a_new_me_small_breakfast: "Hafif bir kahvaltı (yaklaşık 170 kcal): ezme ya da peynirle bir spelt pita (100 kcal'ye kadar), yanında bir sebze – sevdiğin en fazla 3 şeyi seç, örneğin 1 tatlı kaşığı çikolata kreması, 1 tatlı kaşığı fıstık ezmesi ya da bir dilim kaşar (en fazla %22 yağlı). Küçük olduğu için yanında başka bir saatte “Bir de küçük bir öğün” gelir (örneğin bir buçuk saat sonra, 11:30 → 13:00 – başka bir saat de seçilebilir): bir pita daha ve ezme, proteinli yoğurt ve meyve, pirinç patlağı ve peynir, tahıl gevreği ve süt ya da yarım pita ve yumurta – yaklaşık 200 kcal'ye kadar, kendi ✓ işaretiyle. Geriye kalan kısım diğer öğünlere dağıtılır ve her öğün ne kadar eklendiğini gösterir; böylece günün toplamı plandaki gibi kalır. Ankette seçebilir ya da 🔄 ile yalnızca bugün ona geçebilirsin – örneğin kahvaltı geç olduğunda.",
