    faq_a_ai_icon: "Evet – Ayarlar > Görünüm ve Ekran'da. Varsayılan yumuşak baloncuktur; Premium ile süzülen bir beyin ya da robot da seçebilirsin.",
    faq_a_new_me_favorites: "Evet. Ankette (ve ayarlardan yeniden doldururken) her öğün için en fazla 2 seçenek seçebilirsin. İlki menüde görünür, altında ikincisi için bir “ya da” satırı olur – ona dokunmak yalnızca bugün için onu seçer. Kahvaltı zamanında yenmediyse “⏰ Sonra” onu günün ilerleyen saatlerine taşır, kaloriler değişmez.",
    faq_a_theme_mode: "Bazı özel temalar koyu modda en güzel görünür – Suluboya, Kuzey Işıkları, Barbie ve iki ışıltılı tema –; bu yüzden bunlardan birini seçmek uygulamayı koyu moda, başka herhangi bir temayı (roket de dahil) seçmek ise açık moda geçirir. Siyah ve Koyu Gri koyu kalır. Sonra istediğin zaman menüdeki 🌙 ile ya da ayarlardaki Açık Mod ile değiştirebilirsin.",
    faq_a_water_month: "Su takibinde. Bugünün kaydındaki her girişin yanında eklendiği saat yazar, \"Aylık tablo\" ise bütün ayı açar: her günde kaç litre içildiği görünür (günlük hedefe ulaşıldığında ✓) ve bir güne dokunmak o günün girişlerini saatleriyle gösterir.",
