    faq_a_new_me_weight_optional: "Hayır. Anketteki mevcut kilo da hedef kilo da isteğe bağlıdır. Daha sonra bir tartı eklenirse (New Me'deki \"Yolculuğum\" içinde ⚖️ Kilo ya da kilo takibi), ilerleme ilk tartıdan itibaren hesaplanır.",
