    faq_a_room_records: "Pikap en baştan beri odada, koltuğun yanındaki ağaç kütüğünün üstünde. Plakları son yılların büyük hitlerinin resmi kliplerini YouTube'da açar; altında da burada, odada çalan beş sakin ezgi var – çalarken plak döner, \"⏹ Durdur\" ise müziği kapatır.",
    faq_a_room_roof_gifts: "8. anahtarla gelirler. Teleskopa dokunmak içinden bakmanı sağlar: gece gökyüzü yakından – etrafa bakmak için sürükle (ya da oklarla) – ve tamamlanan görevlerin orada bir takımyıldız oluşturur, her görev için bir yıldız; bir yıldıza dokunmak hangisi olduğunu gösterir. Küçük sandığa dokunmak onu açar – şimdilik boş – bir dokunuş daha kapatır.",
