    menu_quick_search: "Hızlı arama",
    nm_times_hint: "İpucu: Her öğünü genelde yediğin en geç saati yazabilirsin – örneğin çoğunlukla 8 civarında yiyorsan 9:00.",
    room_game_marquee: "Yol üstünde – durup keyfini çıkar",
    room_sand_erase_aria: "Yazıyı silmek için ov",
    faq_a_home_note_line: "Ana ekranın ortasındaki satıra yaz ve ➤ (ya da Enter) tuşuna dokun – Notlar'a kaydedilir. Satırın başındaki 📝'ye dokunursan 🛒 olur: o zaman yazdığın şey Alışveriş Listesi'ne gider. Bir kez daha dokun, 🍎 olsun: birkaç harf yaz, eşleşen kayıtlı öğünlerin çıksın; birine dokununca bugünün öğünlerine eklenir. 🎤 ile sesli söylemen yeterli.",
    faq_a_night_mode: "Menüyü ☰ aç ve en üstteki 🌙'ye dokun – tüm uygulama koyulaşır. Aynı yerdeki ☀️ gündüzü geri getirir. Ayarlar'da, Açık Mod altında da var.",
    faq_q_home_note_line: "Ana ekrandan nasıl hızlı not yazarım?",
    faq_q_night_mode: "Gece moduna nasıl geçerim?",
    menu_day_mode: "Gündüz modu",
    menu_night_mode: "Gece modu",
    faq_a_secret_room_yoga: "Ormandaki patikanın sonunda ışıldayan bir kapı var; arkasında, bir şelalenin yanında, orman canlıları – Lumi, Puffi, Nixie ve Sparklet – yarım daire halinde matlarının üzerinde oturuyor, yoga öğretmeni Flora da karşılarında, taşın üstündeki tek matta oturuyor. Flora'ya dokun: gözlerini açar, her şey yaklaşır ve sohbet yavaşça, okumaya zaman bırakarak başlar – Flora herkesin nasıl olduğunu sorar, her canlı kendi adıyla cevap verir (her satırın yanında konuşanın küçük bir resmi olur), sonra da sana yakınındaki insanlarla nasıl hissettiğini sorar. Sohbet cevaplarına göre devam eder – iyi insanlar, zorlandığın biri ya da biraz yalnızlık. Her yol küçük bir görevle (doğrudan Günüm'e eklenebilir; görev bir şey yazmaksa, yazmak için bir yer vardır ve yazılan sihirli günlüğe kaydedilir) ve birlikte üç nefeslik bir duruşla biter. ↩ bir adım geri gider, ✦ yeni bir sohbet başlatır. Bir sonraki anahtar şelaleyi açar: taşa oturunca her şey kaybolur ve yalnızca suyun sesi kalır. Havuzun üzerine eğilince sudan bir soru yükselir – gerçek sen bugün ne yapardı? – ve cevap Günüm'de küçük bir görev olur. Bu sıcak bir an; bir uzmanla konuşmanın yerini tutmaz.",
