    routine_time_taken: "Bu saatte zaten bir şey var: {title}",
    faq_a_new_me_times: "Baştaki ankette ve istediğin zaman New Me ayarları → \"Öğün saatleri\" bölümünde. Rutininde zaten öğün saatleri varsa oradan alınır – ve rutindeki öğünler gizlenip yerlerinde New Me öğünleri gösterilebilir. Yoksa günde kaç öğün (2 öğün + bir ara öğün / 2 öğün + hafif bir akşam yemeği / 2 öğün + bir ara öğün + hafif bir akşam yemeği) ve her birinin ne zaman olacağını seçersin. \"2 öğün + bir ara öğün\" ile bunlar 11:30'da öğle yemeği, 16:00'da ara öğün ve 19:00'da akşam yemeğidir (her biri değiştirilebilir). Bunlar her yerdeki öğün saatlerindir: koridorda, Günüm'de, Rutinim'de ve hatırlatmalarda. Ne seçilirse seçilsin günün kalorisi aynı kalır: çıkarılan kısım diğer öğünlere paylaştırılır.",
