    faq_a_secret_room_diary: "Sadece sen. Günlük sayfaları hesabına kaydedilir; bu yüzden her cihazında durur ve başka kimse göremez. Gizli odadaki masanın üstündeki sihirli günlük onu açar, müzik köşesindeki günlük de. Yeni sayfanın altında katlanmış bir aylık tablo var: sayfası olan her günü bir nokta işaretler, bir güne dokununca o günün sayfaları açılır; orada bir sayfayı silmek de mümkün. Günlük açıldıktan sonra ana menüye de eklenebilir – günlüğün içindeki ya da New Me ayarlarındaki anahtarla.",
    faq_a_secret_room_places: "Orman kapısındaki her giriş kendi anahtarıyla açılır. Arkalarında: denize bakan veranda (küçük masada Alaaddin'in lambası – bir dokunuş ve büyülü bir sisin içinden bir orman ruhu yükselir, etrafta süzülür ve dileğin hakkında bir sohbet başlatır – bkz. “Lamba cini ne yapar?”), gitar ve günlük (gitar kısa, sakin bir ezgi çalar ve kendiliğinden durur, ağaçta asılı üç plağın her biri kendi büyülü ezgisini çalar – tekrar dokununca durur – kütüğün üstündeki günlüğe de yazılır), nefes odası (gün batımında sakin bir göl: suyun üstünde bir lotus feneri yüzer, ona dokun, bir dilek yaz, dilekle birlikte gölün uzaklarına doğru süzülür; sihirli değnekle kuma bırakmak istediğin şeyi yazabilirsin, parmağınla silene kadar kalır) ve ormandaki patika (geceleri açılır, fenerlere dokunmak gündüze geçirir; büyük dalda büyülü bir salıncak asılıdır, bankta oturulur, tabelaya dokununca yakınlaşır: işaretlenecek altı küçük sorunun olduğu bir pano). Kilitli bir girişte kaç anahtar kaldığı görünür. Patikanın sonunda ışıldayan bir kapı şelalenin yanındaki yogaya, oradan da şelalenin kendisine götürür.",
