    dev_weather_preview_label: "Önizleme – yalnızca senin hesabında:",
    faq_a_ai_chat: "Baloncuğa dokununca bir sohbet açılır. Ne yapılacağı seçilir – takvime bir şey, ne yenildiği, bir tarif fotoğrafı ya da yeni bir tablo – ya da sadece yazılır, asistan ne olduğunu kendisi anlar. Yazmak yerine 🎙️ simgesine dokunup konuşmak da mümkün. Takvim için bir kez, her hafta veya her gün seçilebilir. Cevap sohbete gelir; oradan başka bir şeye geçilebilir ya da takvim / yenilenler açılabilir.",
    faq_a_new_me_hall: "New Me büyülü bir ormanın kapısında açılır ve oradaki her giriş bir yerdir: dev ağaçtaki yuvarlak kapı gizli odaya, içi oyuk ağaç gövdesi denize bakan verandaya, mantar ev gitar ve günlüğe, küçük söğüt kemeri nefes odasına, büyük söğüt kemeri ormandaki patikaya götürür; merdivenli çiçek kemerinden ise yıldızlı çatı açılınca yukarı çıkılır. Kilitli bir girişin üzerinde asma kilit görünür. Patikada karakterin Sky süzülür, etrafında da oyun düğmeleri vardır: sıradaki görev, haftanın görevi, tüm New Me'yi içeren sihirli çanta, dünya haritası ve araçlar. Üstteki anahtarlara dokunmak anahtarların nasıl kazanıldığını anlatır.",
    faq_a_new_me_routine_meals: "New Me'de öğünler belirlendiğinde ve Rutinim'de de öğünler olduğunda, New Me bunların gizlenip yerlerinde New Me öğünlerinin gösterilip gösterilmeyeceğini sorar – böylece hiçbir şey iki kez görünmez. Ardından Rutinim, New Me öğünlerini kendi saatlerinde 💎 ve ✓ ile gösterir; bir öğünün adına dokunmak, rutinin hemen üstünde başka bir öğün seçmek ya da saatini değiştirmek için bir pencere açar. Hiçbir şey silinmez: New Me'nin ⚙️ Ayarlar → Rutindeki öğünler bölümünden ya da Rutinim'in ⚙️ menüsündeki “New Me ile senkronize et” kapatılarak geri gelirler. Etkin bir New Me yoksa kendiliğinden geri gelirler.",
    faq_a_room_computer: "“Bugün şimdiye kadar nasıl geçiyor?” diye başlayan küçük bir sohbettir – iyi, yoğun ya da zor – ve adım adım seninle ilerler, sonunda küçük bir göreve kadar (doğrudan Günüm'e de eklenebilir). Cevaplara dokunulabilir ya da serbestçe yazılabilir – yazılanlar en yakın cevaba bağlanır. “↩ Geri” bir adım geri gider, böylece farklı cevap verilebilir; “Yeni sohbet” her an baştan başlatır. Yoğun ya da zor bir günün ardından aynı gün daha sonra bilgisayara dönülebilir: “Geri döndüm...” sohbeti sürdürür. Alttaki yeşil ışık bilgisayarı kapatıp açar. Yalnızca seçimler saklanır, yalnızca bu cihazda ve yalnızca gün sonuna kadar.",
    faq_q_ai_chat: "Asistanla nasıl konuşulur?",
    faq_q_new_me_hall: "New Me'deki koridor nedir?",
    faq_q_new_me_routine_meals: "Rutinim neden New Me öğünlerini gösteriyor?",
    faq_q_room_computer: "Gizli odadaki bilgisayar nasıl çalışır?",
