    pcx_c1a_t: "Mümkünse – 15 dakika gözlerin kapalı. Değilse – yüzüne soğuk su çarp ve biraz soluklanmak için büyük bir bardak su iç.",
    pcx_c1a_tn: "Kısa şekerleme ya da soğuk su",
    pcx_c1b_q: "Duygusal stres doğrudan bedende ve kaslarda birikme eğilimindedir. Biraz gevşemek alevleri düşürmeye yardım eder.",
    pcx_c1b_r1: "Baskı gerçekten bedenimde hissediliyor",
    pcx_c1b_s: "Beden yükü bırakınca kafa her şeyin yolunda olduğu sinyalini alır.",
    pcx_c1b_t: "Omuzlarını aşağı bırak, karnına doğru 3 derin nefes al ve boynunu yavaşça çevir.",
    pcx_c1b_tn: "Gevşeten esneme",
    pcx_c2_o1: "Anlaşılmadığımı / haksızlığa uğradığımı hissetmek",
    pcx_c2_o2: "Hâlâ kaynayan bir öfke",
    pcx_c2_q: "İnsanlarla sürtüşmeler ya da zor konuşmalar, bütün bir günün huzurunu bozabilecek ağır bir tortu bırakır. Bunda seni en çok rahatsız eden ne?",
    pcx_c2a_q: "Görülmediğini ya da anlaşılmadığını hissetmek çok sinir bozucu. Burada kelimelerle dışarı çıkarmak ister misin?",
    pcx_c2a_r1: "Evet, şöyle oldu...",
    pcx_c2a_r2: "Hayır, içine girmek istemiyorum",
    pcx_c2a_s: "Tamamen anlaşılır. Bazen onu bir süreliğine kenara koymak en sağlıklı adımdır.",
    pcx_c2a_t: "Başkalarının yorumunun mutlak gerçek olmadığını kendine hatırlat – ve bu kırgınlığı yarına kadar molaya gönder.",
    pcx_c2a_tn: "Duygusal sınır",
    pcx_c2b_q: "Öfke dışarı çıkması gereken güçlü bir enerjidir, yoksa bizi içten içe kemirir.",
    pcx_c2b_r1: "Sadece öfkemi çıkarmak istiyorum",
    pcx_c2b_s: "O zaman kendine zarar vermeden, güvenle dışarı çıkaralım.",
    pcx_c2b_t: "Bir yastığa yumruk at, 5 dakikalık tempolu bir yürüyüş yap ya da bütün öfkeni bir kâğıda yaz – ve yırt.",
    pcx_c2b_tn: "Bedensel boşalma",
    pcx_c3_o1: "Programda kaos / uzun süren bir işte aksilik",
    pcx_c3_o2: "Başarısızlık hissi / üzerinde çalıştığım bir şey yürümedi",
    pcx_c3_q: "Her şeyin ters gittiği günlerde çaresizlik hissi gelir. Bugün asıl ters giden ne oldu?",
    pcx_c3a_q: "İşler kontrolümüz dışındayken tek kural “kolay hayatta kalma moduna” geçmektir. Bugün neyi iptal edebiliriz?",
    pcx_c3a_r1: "Bazılarını iptal ettim ama hâlâ baskı var",
    pcx_c3a_s: "Beklentileri düşürmek pes etmek değildir – günlük bir bilgeliktir.",
    pcx_c3a_t: "Bugün için bir görev seç ve onu resmen bırak, biraz nefes alacak alan açmak için.",
    pcx_c3a_tn: "Vites düşür",
    pcx_c3b_q: "Hayal kırıklığı acıtır, özellikle emek verdikten sonra. Ama işe yaramayan bir deneme sadece bir bilgidir – kim olduğumuzun tanımı değil.",
    pcx_c3b_r1: "Hâlâ beni çok üzüyor",
    pcx_c3b_s: "Moralinin bozuk olması normal. Kendini eleştirmeden ona yer aç.",
    pcx_c3b_t: "Şimdi seni rahatlatacak küçük bir şey yap (sıcak bir içecek, sevdiğin bir şarkı).",
    pcx_c3b_tn: "Kendine şefkat",
    pcx_c4_o1: "Sessizce, çok fazla insanla konuşmadan",
    pcx_c4_o2: "Beni teselli edecek ya da moralimi yükseltecek küçük bir şey arayarak",
    pcx_c4_q: "Bunun da tam bir yeri var. Kendine biraz şefkat ve sessizlik vermek için her zaman nedenini açıklaman gerekmez. Günün geri kalanını nasıl geçirmek istersin?",
    pcx_c4a_s: "Sessizlik harika bir pil şarj cihazıdır. Bugün biraz mesafe koyabilirsin.",
    pcx_c4a_t: "Önümüzdeki bir saat boyunca telefonunu sessize ya da “Rahatsız Etmeyin”e al.",
    pcx_c4a_tn: "Baloncuk",
    pcx_c4b_s: "Gri günlerde küçük şeyler büyük fark yaratır.",
    pcx_c4b_t: "Bu akşam için güzel bir şey seç (iyi bir film, sıcak bir duş, lezzetli bir yemek).",
    pcx_c4b_tn: "Küçük bir ödül",
    pcx_c_end1: "Hatırlamaya değer: zor bir gün zor bir hayat değildir – koca bir kitabın sadece bir sayfasıdır. Yarın yeni bir gün.",
    pcx_c_end2: "Sakin ve yumuşak bir akşam geçir. Biraz daha içini dökmen gerekirse ya da sonra zorlaşırsa – buradayım. Sadece geri gel, konuşuruz.",
    pcx_c_o1: "Fiziksel olarak kötü / deli gibi yorgun",
    pcx_c_o2: "Biriyle tatsız bir şey / tartışma / kırgınlık",
    pcx_c_o3: "Her şey ters gidiyor / planlar tamamen suya düştü",
    pcx_c_o4: "Belirgin bir sebebi olmayan ağır bir his",
    pcx_c_q: "Ah, bunu duymak üzücü... böyle günler gerçekten insanı tüketebilir. Bir gün böyle olabilir ve bu tamamen normal. Bugün seni en çok neyin zorladığını paylaşmak ister misin?",
    pcx_cr1_s: "Sihirli bir değnekle yok olmamış olması tamamen normal. Böyle günleri sadece en az çabayla atlatmak gerekir. Hisle savaşma – bu günün sakince bitmesine izin ver.",
    pcx_cr2_o1: "🌬️ Birlikte 5 nefes",
    pcx_cr2_o2: "✍️ 3 cümle yaz",
    pcx_cr2_s: "Kafan taştığında en iyisi odağı bedene taşımaktır. Birlikte 5 yavaş nefes alabiliriz ya da buraya kafanda dönen her şey hakkında 3 cümle yazabilirsin – dışarı çıkarmak için.",
    pcx_cr3_s: "Kesinlikle her şey yoluna girecek. Daha önce de zor günlerden geçtin ve atlattın; bu gün de bitmek üzere. Bugün elinden gelenin en iyisini yaptın ve bu fazlasıyla yeterli. Sarılıyorum! 🤗",
    pcx_cr_me: "Merhaba, geri döndüm... hâlâ zor / daha da yorucu oldu",
    pcx_cr_o1: "Ağır his geçmedi, bu sinir bozucu",
