    faq_a_dictation: "Evet – hızlı notun ya da defterdeki bir yazı sayfasının köşesindeki 🎤 mikrofona dokun ve konuş: sözcükler sen konuşurken uygulamanın dilinde yazılır. Durdurmak için yeniden dokun. İlk seferde tarayıcı mikrofon için izin ister. Chrome / Android'de ve iPhone'da Safari'de çalışır. Bilgisayarda bir mikrofon ve Chrome, Edge ya da Safari gibi bir tarayıcı gerekir – bir şey eksikse mesaj tam olarak neyin eksik olduğunu söyler.",
    faq_q_dictation: "Yazmak yerine konuşabilir miyim?",
    faq_a_secret_room: "New Me içinde sadece sana ait bir oda – dev bir ağacın içinde bir ev. Her seferinde bir duvar görürsün ve oklarla (ya da kaydırarak) dönersin. İlk anahtar, 3 farklı günde bir öğüne ✓ koyduktan sonra gelir ve kapıyı açar – onunla birlikte tüm odayı da: bilgisayarı, oyunu, pikabı, içinde kütüphane olan rafı ve kediyi. Sonra biten her görev (haftanın görevi de) bir sonraki yeri açan bir anahtar verir: yıldızlı çatı, denize bakan veranda, gitar ve günlük, nefes odası, ormandaki patika ve yoga, şelale ve çatıda bir sürpriz – ve 8. görev, içinde geçmişten gelen mektup olan bir şişeyi denizden getirir. Bir şey açıldığında, bir ok yolu gösterir. Oyun makinesinin altındaki küçük kapı da açılır – şimdilik arkasındaki dolap boş. Yıldızlı çatıda dokunduğun yıldız kayan yıldız gibi düşer, kedi de minderde oturur.",
