    weather_failed: "Hava durumu şu an kontrol edilemedi.",
    weather_location_denied: "Konuma erişim yok – tarayıcı ayarlarından izin verip tekrar dene.",
    faq_a_home_focus: "Ana ekranın üstündeki ◎'e dokun: şimdiki tek şey – bu saatte olan ya da bugünün listesindeki sıradaki şey – büyük bir ✓ ve Hızlı Not dışında her şey kaybolur. ✓'ten sonra sıradaki şey görünür. Üstteki \"Odak modu ✕\" her şeyi geri getirir.",
    faq_a_home_search: "Menüyü ☰ aç – arama en üstte. En az 2 harf yaz: sonuçlar notlarından, alışveriş listenden, takviminden, tariflerinden, defterlerinden (başlıklar ve sayfa metni), hedeflerinden, tablolarından ve kitaplarından türe göre gruplanarak gelir – birine dokunup doğrudan oraya git.",
    faq_a_my_day: "Günüm, eskiden Bugüne Bir Bakış ve Rutinim olanları tek bir zaman çizelgesinde birleştirir. Ana ekranın altında ne kadarının yapıldığını, şimdi ya da sırada ne olduğunu (hızlı ✓ ile) görürsün; başlığın yanında da +1 ile bir bardak su eklenir. Dokun (ya da yukarı kaydır), bütün gün açılsın: üstte saati olmayanlar, sonra saat saat her şey – takvimdeki görevler, etkinlikler ve toplantılar, haftalık sabit saatler, bugünün rutini, hedeflerinin küçük adımları ve New Me öğünleri – ve bir \"şimdi\" çizgisi. Görevler, Rutin ya da Toplantılar ve etkinlikler diye filtreleyebilirsin. Buradaki ✓ her yerdeki ✓ ile aynıdır (Rutinim, Hedeflerim, takvim) ve köşede bir papatya açtırır. \"Rutini düzenle\" Rutinim'i açar (menüde de var), \"＋ Bugüne ekle\" ise bugüne bir görev ekler. \"Günüm\" başlığına (ya da üstteki küçük çubuğa) dokunmak onu yeniden kapatır.",
