    vision_goal_delete_routine_note: "Rutinim'deki öğeleri de silinecek.",
    faq_a_goal_small_steps: "Hedeflerim'deki her hedef bir yoldur: geride kalan duraklar, bugünün parlayan taşı ve sondaki kupa. Bir hedefe küçük bir adım ver – her gün ya da her hafta seçtiğin bir günde – zor bir günde bile yapılabilecek bir şey, örneğin '10 dakika hafif koşu'. Bugünün tüm küçük adımları Hedeflerim'in en üstünde ve Günüm'de, her biri hızlı bir ✓ ile görünür; bir hedefin yolunun altındaki '✓ Bugün yaptım' son 7 günün noktalarını doldurur. '10'a doğru yolda · durmak yok' notu bilerek en üstte kalır: mükemmel olmak zorunda değiliz – ilerlemek için her gün biraz yapmak yeter.",
