    faq_a_new_me_advanced: "Gelişmiş mod, 20 görevin hepsinden sonra hediyeyle birlikte açılır ve 🎁 Hediyen bölümünden açılıp kapatılabilir. New Me'ye altın görünüm, serbest menü oluşturma – her değişiklik kalori sınırı olmadan tüm seçenekleri gösterir – ve bir 📊 Gelişmiş istatistikler ekranı kazandırır: son 30 günün kalorileri ile planın karşılaştırması, haftanın günlerine göre iyi günler, hedefe ne zaman ulaşılacağının tahminiyle kilo eğilimi, akşam değerlendirmesinin ortalamaları ve görevlerin geçmişi.",
