    nm_gift_intro: "{n} görevin hepsi, adım adım. İşte bekleyen:",
    nm_gift_title: "Hediyen",
    faq_a_new_me_letter_gift: "New Me'nin başında (ya da daha sonra Görevler'de) gelecekteki kendine bir mektup yazılabilir. Mühürlendikten sonra açılana kadar okunamaz ve düzenlenemez: gizli odada denizden gelen şişede ya da 20 görevin hepsinin sonunda – orada bir hediye de bekler.",
    faq_q_new_me_letter_gift: "Geçmişten mektup nedir?",
    faq_a_new_me_challenges: "🏆 Görevler'de 20 görev var: 10 büyük (örneğin şekersiz 5 gün, karbonhidratsız bir hafta ya da bir ayda 4 kg vermek – her gün kalori açığı, antrenman ve şekersizlik) ve 10 mini – şekersiz tarçınlı kahve gibi bir haftalık küçük alışkanlıklar. Bir görev seçildiğinde ne zaman başlanacağı sorulur: bugün, yarın, gelecek hafta ya da başka bir tarih. Bir büyük ve bir mini görev aynı anda sürebilir. Süren görev menünün en üstünde ve Günüm'de görünür, gün için bir ✓ ile. Görevin her haftası, görevi bozmayan bir serbest gün (🍕) getirir ve işaretlenmeyen bir gün serbest gün sayılır – bugün ve dün işaretlenebilir. Bazı günler kendiliğinden işaretlenir: Antrenman Takibi'nde 20 dakikalık bir antrenman ya da ✓ alan menü öğünleri. Her görevde tam olarak neyin sayıldığını gösteren bir ⓘ var (örneğin karbonhidratların tam listesi) – görevin içinde ve Günüm'de yanında. Bunların altında, 🌱 Kişisel gelişim'de bir haftalık 48 küçük görev var (20'ye dahil değildir) – bkz. “Haftanın görevi nedir?”.",
    faq_q_new_me_challenges: "New Me'deki görevler nasıl işliyor?",
