    nm_tile_challenges: "Görevler",
    faq_a_workout_calories: "Evet. Her antrenman için yakılan kalorinin tahmini hesaplanır – türe, süreye ve son kilona göre (koşu ve bisiklette mesafe girilince hıza göre de). Antrenman listesinde ve aylık özette (Yakılan) görünür ve o günün kalori bütçesine eklenir: Günlük Öğün Takibi'nde, Kalori ve Kilo Ölçümleri'nde ve New Me'nin halkasında. Bu bir tahmin, bu yüzden ~ ile gösterilir.",
    faq_q_workout_calories: "Antrenmanlar günlük kalorime sayılıyor mu?",
    faq_a_new_me_flexible_menu: "Evet. Ankette ve ayarlarda günde kaç öğün olacağı seçilir – 2 öğün + bir ara öğün / 2 öğün + hafif bir akşam yemeği / 2 öğün + bir ara öğün + hafif bir akşam yemeği – ve öğün kartındaki ➖ onu çıkarır (en az 3 kalır); '➕ Geri ekle' geri getirir. Her durumda günün kalorisi aynı kalır: çıkarılan kısım diğer öğünlere paylaştırılır ve her öğünün altında ne kadar eklendiği ve neler eklenebileceği yazar. Öğündeki ✏️ Düzenle metnini açar – istediğini değiştir (ör. ekmeksiz ya da bir yumurta daha) ve AI kaloriyi ve proteini yeniden hesaplar. 🔄 Değiştir; menüden seçenekler, ⭐ Kayıtlı ve ✨ Yaz sunar; her değişiklik yalnızca bugün için ya da bundan sonrası için olabilir. 'Bütün gün'ün sonunda da ➕ Yiyecek ekle var – menü dışında yenileni yaz, AI hesaplayıp bugüne eklesin (✕ siler).",
    faq_q_new_me_flexible_menu: "New Me'de öğün sayısını değiştirebilir veya kendi öğünümü yiyebilir miyim?",
