    books_menu_label: "Okuma Köşesi",
    faq_a_goal_tasks_peek: "Üç tür: aktif bir günlük meydan okumanın her günkü görevleri (örneğin 'Karbonhidratsız') – meydan okuma tamamlanana kadar her gün görünürler ve orada ✓ işaretlemek o günü hedefte de işaretler (tersi de geçerlidir); 📅 planladığınız hedef durakları – kendi tarihlerinde ve takvimde de; ve 👣 diğer her hedefin küçük adımı – hedefi eklerken ya da düzenlerken belirlersiniz (her gün ya da her hafta seçtiğiniz bir günde). Bunlar Hedeflerim'in en üstündeki 'Bugünün küçük adımları' ile aynı adımlardır, her biri kendi hedefinin simgesiyle. O gün kaydedilen bir +1 küçük adımı otomatik olarak işaretler (küçük adım tartılmanın kendisiyse, tartılmak da işaretler).",
