    faq_a_goal_days_challenge: "Hedeflerim'de ＋ simgesine (ya da hazır '🔥 8 gün' örneğine) dokunun, '📆 Günlük meydan okuma' seçeneğini seçin, gün sayısını girin ve her gün ne yapacağınızı ekleyin (örn. '30 dakikalık yürüyüş', 'Menüme göre beslenmek'). Her gün meydan okumanın yolunun altında o günün görevlerini işaretleyin – hepsi işaretlendiğinde gün sayılır, yol bir taş ilerler ve 🔥 seriniz uzar (günlük görev yoksa tek bir '✓ Bugün yaptım' düğmesi vardır). Bir görevin yanındaki 🔁 düğmesi onu seçtiğiniz saatte Rutinim'e ekler: orada işaretlemek hedefte de işaretler, tersi de geçerlidir. Normal bir hedefin durakları da aynı şekilde Rutinim'e eklenebilir.",
