    vision_tagline: "Büyük hedefler, küçük adımlar.",
    faq_a_app_tour: "Tur, ilk girişte bir kez otomatik açılır. Bölümleriyle başlar – birine dokununca doğrudan oraya gidersin – sonra uygulamanın her bölümünü (ana ekran, yapay zekâ asistanı ve menüdeki her öğe) ve Ayarlar'ın beş grubunu kısa açıklamalarla gösterir ve bazılarının içine de göz atar (örneğin örnek bir hedef yolu, çanta ve Google Calendar). Devam ilerletir, Geri geri götürür, Bu bölümü geç sonraki bölüme atlar ve ✕ turu kapatır. Turu istediğin zaman Ayarlar > Yardım ve Kullanım > Uygulama Turu'ndan yeniden izleyebilir ve kaldığın yerden devam edebilirsin. Devam ve Geri her zaman ekranın altında aynı yerde durur; bilgisayarda klavyenin ok tuşları da çalışır.",
