    apptour_m_study_text: "Çantanız: hayatın her alanı için bir cep – içinde defterler, tablolar ve görevler.",
    apptour_m_vision_link: "Bir duraktaki 📅 onu takvime ekler; küçük adımlar ve günlük meydan okumanın görevleri Günüm'de görünür, ilerleme bir sayıyı ya da kilonu da takip edebilir.",
    apptour_m_vision_text: "Hedeflerin küçük adımlardan oluşan yollar – bugünün adımları en üstte. Hadi içine bakalım 👇",
    apptour_m_myweek_link: "Google Calendar ile senkronize olur (Ayarlar'da).",
    apptour_m_myweek_text: "Aylık takvim, hatırlatmalı tekrarlayan haftalık görevler ve tüm tarihli etkinliklerin. Bir de haftanın toplantıları için kâğıt bir ajanda 🤝.",
    apptour_m_newme_link: "Her şey Günlük Öğün Takibi'nde ve Günüm'de sayılır; kilo, Kalori ve Kilo Ölçümleri ile ortaktır.",
    apptour_m_newme_text: "Büyülü bir oyun dünyasında 1.300 / 1.500 kalorilik beslenme planı: ✓ ile bugünkü menü, üç yolla değişim – menüden, kayıtlı öğünlerinden ya da ne yediğini yapay zekâya yazarak, kaloriyi de o hesaplar – alışveriş listesi, öğün hatırlatmaları ve başarılar, ölçüler ve fotoğraflarla bir ilerleme yolculuğu. Ayrıca 🏆 20 görev – sonunda bir hediyeyle – ve haftanın görevi.",
