    apptour_ai_food_link: "Doğrudan Günlük Öğün Takibi'ne ve bugünün toplamına gider.",
    apptour_ai_food_text: "Ne yediğini yaz – kaloriler senin için tahmin edilip kaydedilir.",
    apptour_newme_short_text: "New Me'yi açar – bugünkü menü doğrudan ana ekranda.",
    apptour_ai_link: "Düğmedeki küçük 1 rozeti, günlük “bugün en önemli şey” hatırlatmasıdır.",
    apptour_ai_text: "Basit kelimelerle yaz, asistanın gerisini halleder: kalorileri kaydeder, planları takvime koyar, fotoğraftan tarif okur ve tablolar kurar.",
    apptour_quicknote_link: "📝 ve 🛒 tam listeleri açar; 🍎 kayıtlı bir öğünü Günlük Öğün Takibi'ne ekler.",
    apptour_quicknote_text: "Hızlıca bir şey not al – Notlar'a ya da doğrudan Alışveriş Listesi'ne.",
    apptour_routine_link: "Bir alışkanlık, Antrenman Takibi'ne otomatik olarak antrenman kaydedebilir.",
    apptour_routine_text: "Saat saat günlük rutinin, sekmelerde (çocuklar, ders, iş…). Alışkanlıklar ve seriler oluşturmak için her gün ✓ işaretle; 📅 tüm ayı gösterir.",
