    nm_extras_title: "Bugün ayrıca yenenler",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "İçecek adını ve kalorisini gir",
    nm_drink_more: "+ Başka içecek",
    nm_drink_add: "Ekle",
    nm_drink_name_ph: "İçecek (ör. meyve suyu)",
    nm_drinks_hint: "İçeceğin adını yazman yeterli – kaloriler otomatik hesaplanır ve sayı değiştirilebilir.",
    nm_slot_drinks: "İçecekler",
    faq_a_new_me_tracking: "New Me'nin üstündeki sıradaki göreve dokun, sonra ✓ Yedim'e dokun; sıradaki öğün yenmiş olarak işaretlenir – her öğünde ✓ olan tüm menü yandaki “Bütün gün”de, bugünün öğünleri de ana ekrandaki Günüm'de görünür – oradaki bir öğüne dokunmak (ya da fareyi üzerine getirmek) tam olarak ne yeneceğini ✓ ve Değiştir ile birlikte gösterir. Her şey Günlük Öğün Takibi ile senkronizedir: plan öğünleri, içecekler ve başka yerden eklenen her şey (örneğin hızlı eklemeden bir kahve) New Me'de ve Günüm'de birlikte sayılır – daha önce yazılan hiçbir şeyin üzerine yazılmaz ve bir ✓'yi kaldırmak yalnızca New Me kısmını kaldırır. Bugünün tüm öğünleri işaretlenince küçük bir kutlama olur. “İçecekler” bölümüne günün içecekleri girilir – hepsi birlikte ~150 kcal'ye kadar, yani her biri ~50 kcal'ye kadar yaklaşık 3 içecek. İçeceğin adını yazmak yeterli, kaloriler yapay zekâ ile otomatik doldurulur. İki kahve/çay satırında ayrıca “Süt? Ne kadar?” alanı vardır (örneğin “biraz” veya “50 ml”) ve hesap güncellenir; sayı eklemeden önce ve sonra da değiştirilebilir. Adı ve kalorisi olan bir içecek, bir sonraki adıma geçer geçmez otomatik kaydedilir – Ekle'ye dokunmak isteğe bağlıdır. Bir içeceği sürekli içecek olarak kaydetmek için yanındaki ☆'a dokun – sürekli içecekler İçecekler kartının üstünde düğme olarak görünür ve tek dokunuş onları güne ekler. ⭐ bir öğünü kayıtlı öğün olarak kaydeder. “Günlük tablo” yenenleri kalori ve proteinle gösterir. Ana ekranın üstünde odak modunun yanındaki küçük 💎 onu doğrudan açar. Kalori ve protein değerleri yapay zekâ tahminleridir ve hata içerebilir. Hepsini yemedin mi? İşaretli bir öğünün altındaki “Hepsini yemedin mi?” porsiyonun çeyreğini, yarısını veya dörtte üçünü – ya da yazdığını hesaplayarak – düşer ve günün kalorileri güncellenir.",
    faq_q_new_me_tracking: "New Me'de ✓, değiştirme ve kaloriler nasıl çalışır?",
    faq_a_new_me_what: "New Me, iki hazır planı olan ayrı bir günlük menü programıdır – 1.300 veya 1.500 kalori – 2 ana öğün ve 2 ara öğünden oluşur, her biri için 3 seçenek vardır. Premium'un tamamını içerir. Fiyat: aylık $11.99 (istendiğinde iptal) ya da tek seferlik $99.99, ömür boyu. Menüdeki 💎 New Me'den açılır. Başlamadan önce, kabul edilmesi gereken tıbbi bir uyarıyla başlayan kısa bir anket vardır. Program yalnızca genel bilgidir; doktorun veya klinik diyetisyenin yerini tutmaz.",
    faq_q_new_me_what: "New Me nedir ve nasıl edinilir?",
