    nm_disclaimer_p4: "4. Sorumluluğun sınırlandırılması. Programın kullanımı tamamen kullanıcının kendi riskindedir. Uygulamanın geliştiricileri ve işletmecileri; programın, menülerinin veya yalnızca yaklaşık tahminlerden ibaret olan kalori ve protein değerlerinin kullanımından doğan, sağlığa ilişkin veya başka nitelikteki hiçbir doğrudan ya da dolaylı zarardan sorumlu tutulamaz.",
    nm_disclaimer_p3: "3. Tıbbi onay olmaksızın aşağıdaki kişilere yönelik değildir: hamile veya emziren kadınlar, 18 yaşından küçükler, halihazırda veya geçmişte yeme bozukluğu bulunan kişiler, kronik veya altta yatan bir hastalığı (diyabet, kalp, böbrek veya karaciğer hastalığı dahil) bulunan kişiler ya da düzenli olarak ilaç kullanan kişiler; tedaviyi yürüten hekimden açık onay alınmış olması hali saklıdır.",
    nm_disclaimer_p2: "2. Plan seçimi. 1.300 kalorilik veya 1.500 kalorilik planın seçimi yalnızca kullanıcının kendi takdirinde ve sorumluluğundadır. Kalori kısıtlamalı herhangi bir diyete başlamadan önce bir hekime veya klinik diyetisyene danışılması tavsiye edilir.",
    nm_disclaimer_p1: "1. Yalnızca genel bilgi. New Me programı ve menüleri genel beslenme bilgisi sunar ve tıbbi, diyetetik veya başka herhangi bir mesleki tavsiye niteliği taşımaz. Bir hekim veya lisanslı bir klinik diyetisyen tarafından yapılacak konsültasyon, teşhis ya da tedavinin yerine geçmez. Beslenmede herhangi bir değişiklik yapılmadan veya fiziksel aktiviteye başlanmadan önce bir hekime danışılmalıdır.",
