    faq_q_daily_focus_prompt: "Bugün yapmam gereken en önemli şeyi soran küçük hatırlatma nedir?", faq_a_daily_focus_prompt: "Bu bir Premium günlük hatırlatmadır: günde bir kez yapay zeka asistanı simgesinde küçük bir “1” rozeti belirir. Bugün yapman gereken en önemli şeyi soran bir baloncuğu açmak için rozete dokun; baloncukta hemen 5 hazır öneri (her gün değişirler ve taze kalmaları için bütün bir yıl boyunca farklı temalar arasında dönerler) ve kendi cevabını yazmak için 'Diğer' çıkar - birden fazlasını seçebilirsin. Ekle'ye dokun; seçimlerin 'Günüm'ün üstünde küçük hatırlatma etiketleri olarak görünür (işaretlenecek görevler değildir). ✕ ile kapatırsan ya da dışına dokunursan rozet kaybolmak yerine günün geri kalanında yalnızca soluklaşır. Varsayılan olarak açıktır, ama Ayarlar > Kişiselleştirme ve Takvim bölümünden kapatabilirsin. Bugün uygun değil mi? '🌙 Bugün değil'e dokunun – rozet yarına kadar kaybolur, sonra soru her zamanki gibi geri gelir. Önerilerden biri kendi hayatınızdan gelir – ayın hedefindeki bir sonraki adım ya da bugünkü okuma. Her gün yeni bir başlangıçtır.",
